package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Real HTTP route/header/body handling over explicit service doubles; global security/CSRF remains root integration. */
class FormalPublicationControllerTest {
 PermissionSchema json;ApplicationSessionIdentity identities;ApplicationSessionIdentity.Verified subject;FormalAgentPublicationService publishing;AgentPublicationAuthority authority;FormalAgentAcceptanceService decisions;FormalEvaluationScoreBindingService bindings;MockMvc mvc;FormalScoreBindingSchemaTest input;
 @BeforeEach void setup()throws Exception{json=new PermissionSchema();identities=mock(ApplicationSessionIdentity.class);subject=mock(ApplicationSessionIdentity.Verified.class);when(identities.requireCurrent(any(),any())).thenReturn(subject);publishing=mock(FormalAgentPublicationService.class);authority=mock(AgentPublicationAuthority.class);decisions=mock(FormalAgentAcceptanceService.class);bindings=mock(FormalEvaluationScoreBindingService.class);input=new FormalScoreBindingSchemaTest();mvc=MockMvcBuilders.standaloneSetup(new FormalAgentPublicationController(identities,publishing,authority,json),new FormalAgentAcceptanceController(identities,decisions,bindings,input.schema,json)).build();when(publishing.publish(eq(subject),eq("1"),anyString(),any())).thenReturn(json.object().put("state","PROCESSING"));when(publishing.receipt(eq(subject),eq("1"),anyString())).thenReturn(json.object().put("state","PROCESSING"));when(bindings.recover(eq(subject),eq("1"),anyString(),any())).thenReturn(json.object().put("schema_version","1.0.0"));}
 @Test void publishRoutesActualSubjectAndOriginalKey()throws Exception{mvc.perform(post("/api/formal-agent-publications").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1").header("Idempotency-Key","original-publication-key").contentType("application/json").content("{}")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verify(publishing).publish(eq(subject),eq("1"),eq("original-publication-key"),eq("{}".getBytes()));}
 @Test void duplicatedContextFailsBeforeService()throws Exception{mvc.perform(post("/api/formal-agent-publications").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1","1").header("Idempotency-Key","original-publication-key").contentType("application/json").content("{}")).andExpect(status().isUnprocessableEntity());verifyNoInteractions(publishing);}
 @Test void originalLookupNeverCallsPublish()throws Exception{mvc.perform(get("/api/formal-agent-publication-operations/original-publication-key").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1")).andExpect(status().isOk());verify(publishing).receipt(subject,"1","original-publication-key");verify(publishing,never()).publish(any(),anyString(),anyString(),any());}
 @Test void recoveryRoutesCompleteOriginalBodyWithoutMutationKey()throws Exception{var outer=json.object().put("schema_version","1.0.0").put("original_key","original-binding-key");outer.set("request",input.body());mvc.perform(post("/api/formal-evaluation-score-bindings/recovery").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1").contentType("application/json").content(input.general.canonical(outer))).andExpect(status().isOk());verify(bindings).recover(eq(subject),eq("1"),eq("original-binding-key"),any());verify(bindings,never()).bind(any(),anyString(),anyString(),any());}
 @Test void recoveryRejectsNewMutationKey()throws Exception{mvc.perform(post("/api/formal-evaluation-score-bindings/recovery").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1").header("Idempotency-Key","new-key-forbidden").contentType("application/json").content("{}")).andExpect(status().isUnprocessableEntity());verifyNoInteractions(bindings);}
 @Test void absentProfessionalAuthoritySurfacesActualUnavailableError()throws Exception{when(publishing.publish(any(),anyString(),anyString(),any())).thenThrow(new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));mvc.perform(post("/api/formal-agent-publications").header("X-Schema-Version","1.0.0").header("X-Context-Revision","1").header("Idempotency-Key","original-publication-key").contentType("application/json").content("{}")).andExpect(status().isServiceUnavailable());}
}
